<script setup lang="ts">
import {normalize,type Product,type CartLine} from '@ellas/shared';
const props=withDefaults(defineProps<{product:Product;persist?:boolean}>(),{persist:true});const emit=defineEmits<{add:[lines:CartLine[]];pending:[value:boolean]}>();
const colorCode=ref('');const colorQuery=ref('');const quantities=reactive<Record<string,string|number>>({});const error=ref('');const notice=ref('');
const color=computed(()=>props.product.colors.find(c=>c.code===colorCode.value));
const colors=computed(()=>props.product.colors.filter(c=>normalize(c.name+' '+c.code).includes(normalize(colorQuery.value))));
const total=computed(()=>color.value?.sizes.reduce((n,size)=>n+(Number(quantities[colorCode.value+':'+size])||0),0)||0);
const pending=computed(()=>Object.values(quantities).some(v=>String(v)!==''&&Number(v)!==0));
const selection=useSelection();
onMounted(()=>{const draft=props.persist?selection.drafts[props.product.reference]:undefined;if(draft){colorCode.value=draft.color;Object.assign(quantities,draft.quantities);}});
watch([colorCode,quantities],()=>{if(props.persist)selection.drafts[props.product.reference]={color:colorCode.value,quantities:{...quantities}};},{deep:true});
watch(pending,value=>emit('pending',value));watch(()=>props.product.reference,()=>{colorCode.value='';colorQuery.value='';for(const key in quantities)delete quantities[key];error.value='';notice.value='';});
function add(){error.value='';notice.value='';if(!color.value)return;const lines:CartLine[]=[];for(const size of color.value.sizes){const quantity=Number(quantities[colorCode.value+':'+size]||0);if(!Number.isInteger(quantity)||quantity<0||quantity>10000){error.value='Escribe cantidades enteras entre 0 y 10.000 en cada talla.';return;}if(quantity)lines.push({reference:props.product.reference,name:props.product.name,image:props.product.imageSmall,color:color.value.code,colorName:color.value.name,size,quantity});}if(!lines.length){error.value='Indica al menos una cantidad.';return;}emit('add',lines);}
function clearAdded(){if(!color.value)return;for(const size of color.value.sizes)delete quantities[colorCode.value+':'+size];notice.value='Prendas añadidas. Puedes elegir otro color o buscar otra prenda.';}
defineExpose({clearAdded,pending});
</script>
<template><section class="order-configurator"><div class="order-product-intro"><img :src="product.imageSmall" :alt="product.name" width="120" height="150"/><div><span class="eyebrow">{{product.reference}} / {{product.category}}</span><h2>{{product.name}}</h2><p>{{product.composition}} <span v-if="product.weight">· {{product.weight}} g/m²</span></p><div class="order-product-links"><NuxtLink :to="`/catalogo/${product.slug}`" target="_blank" class="text-link">Ficha y medidas <AppIcon name="ExternalLink" :size="14"/></NuxtLink><CompareButton :reference="product.reference"/></div></div></div><div class="config-step-title"><span>01</span><h3>¿De qué color?</h3><b v-if="color">{{color.name}}</b></div><input v-if="product.colors.length>18" v-model="colorQuery" aria-label="Buscar un color" placeholder="Buscar un color…" class="color-search"/><div class="order-colors"><button v-for="c in colors" :key="c.code" type="button" :aria-pressed="colorCode===c.code" :aria-label="`${c.name} (${c.code})`" :class="{selected:colorCode===c.code}" @click="colorCode=c.code;notice='';error=''"><i :style="{backgroundColor:c.hex,backgroundImage:c.swatch?`url(${c.swatch})`:undefined}"/><span>{{c.name}}<small>{{c.code}}</small></span><AppIcon v-if="colorCode===c.code" name="Check" :size="16"/></button></div><template v-if="color"><div class="config-step-title"><span>02</span><h3>Una cantidad por talla</h3></div><div class="order-sizes"><label v-for="size in color.sizes" :key="color.code+size"><span>{{size}}</span><input v-model="quantities[color.code+':'+size]" type="number" min="0" max="10000" step="1" inputmode="numeric" placeholder="0" :aria-label="`Cantidad ${color.name}, talla ${size}`" @input="error='';notice=''"/></label></div><p class="fine-print">Solo aparecen tallas incluidas para {{color.name}}. Las opciones no indican stock.</p><p v-if="error" role="alert" class="field-error">{{error}}</p><button type="button" class="button dark full order-add" :disabled="!total || !product.source.reviewed" @click="add"><AppIcon name="Plus"/>Añadir {{total}} prendas en {{color.name.toLowerCase()}}</button></template><p v-else class="config-empty">Elige un color para repartir las cantidades por talla.</p><p v-if="notice" role="status" class="added-message">{{notice}}</p></section></template>
